import{z as A,x as d,o as r,c as B,q as E,j as o,D as t,d as s,s as l,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"拟阵理论","description":"","frontmatter":{"title":"拟阵理论","date":"2026-09-27T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/matroid-theory.md","filePath":"cs/matroid-theory.md","lastUpdated":1791063341000}'),p={name:"cs/matroid-theory.md"};function m(c,a,h,u,D,C){const n=d("Mermaid");return r(),B("div",null,[a[2]||(a[2]=E('<h1 id="拟阵理论" tabindex="-1">拟阵理论 <a class="header-anchor" href="#拟阵理论" aria-label="Permalink to &quot;拟阵理论&quot;">​</a></h1><div class="epigraph"><p>贪心为什么有时对有时错？拟阵给出裁决线：独立系满足交换公理，贪心就从局部最优走到全局最优。</p><footer>—— 据 Whitney (1935) 拟阵公理；Edmonds (1971) 贪心与交并</footer></div><p><a href="/cs/slope-trick">Slope Trick</a> 用凸性担保 DP 转移的安全，本课用<strong>交换性</strong>担保贪心的安全。最小生成树里 Kruskal 从不出错，同样的「每次挑最便宜」换到别的场景就翻车——缺口是给出贪心可用的精确条件：<strong>拟阵</strong>。本课不展开图拟阵以外的几何或表示论内容。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>拟阵是一个二元组 \\(M=(E,\\mathcal I)\\)：\\(E\\) 是_ground set_，\\(\\mathcal I\\subseteq 2^E\\) 是独立集族，满足三公理——空集独立；独立集的子集独立（遗传）；两个独立集若 \\(|A|\\lt|B|\\)，则存在 \\(x\\in B\\setminus A\\) 使 \\(A\\cup\\{x\\}\\) 仍独立（交换）。问题：为什么交换公理恰好是贪心的生死线？</p><p><span class="marginnote">术语翻译：ground set（底集）= 候选元素全体；independent（独立）= 被认可的可行集合；rank（秩）= 最大独立集的大小，\\(r(A)\\) 也读作「\\(A\\) 的秩」。</span></p><p><span class="marginnote">数字实例：图拟阵 \\(M_G\\)——\\(E\\) 是边集，独立 = 无环（森林）。\\(A=\\{\\}\\)、\\(B=\\{\\)ab, bc\\(\\}\\)，交换公理给出可从 \\(B\\) 拿 ab 接进 \\(A\\)。这正是 Kruskal 每步「能不能接」的形式化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>拟阵上的<strong>贪心定理</strong>：给每个元素权重，要求最大权独立集，按权从大到小试插、能插则插，全局最优。算法与 Kruskal 同构：排序、逐一 try-include。判独立用并查集（图拟阵）或按拟阵类型定制的 oracle。</p>',9)),(r(),o(i,null,{default:t(()=>[l(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%85%83%E7%B4%A0%E6%8C%89%E6%9D%83%E9%99%8D%E5%BA%8F%22%5D%20--%3E%20B%7B%22%E5%8A%A0%E5%85%A5%E5%90%8E%E4%BB%8D%E7%8B%AC%E7%AB%8B%3F%22%7D%0A%20%20B%20--%3E%7C%22%E6%98%AF%22%7C%20C%5B%22%E7%BA%B3%E5%85%A5%E8%A7%A3%E9%9B%86%22%5D%0A%20%20B%20--%3E%7C%22%E5%90%A6%22%7C%20D%5B%22%E6%B0%B8%E4%B9%85%E4%B8%A2%E5%BC%83%22%5D%0A%20%20C%20--%3E%20E%5B%22%E7%BB%A7%E7%BB%AD%E4%B8%8B%E4%B8%80%E5%85%83%E7%B4%A0%22%5D%0A%20%20D%20--%3E%20E%0A%20%20E%20--%3E%7C%22%E9%81%8D%E5%8E%86%E5%AE%8C%22%7C%20F%5B%22%E6%9C%80%E5%A4%A7%E6%9D%83%E7%8B%AC%E7%AB%8B%E9%9B%86%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：拟阵像「乐高自由拼」——任何合法拼好的两个作品，小的那个永远可以从大的那里搬一块过来接着拼（交换公理）。贪心敢「只看眼前最贵的一块」，正因为搬块永远不锁死后路。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"证明骨架用交换：设贪心解 \\(G\\)、最优解 \\(O\\)，若 \\(|O|\\gt|G|\\)，交换公理保证能从 \\(O\\setminus G\\) 取元素扩 \\(G\\) 仍独立；又因贪心按权序取过该元素却没取，说明权不大于 \\(G\\) 中对应元素——不断替换后 \\(O\\) 可变成 \\(G\\)，故 \\(G\\) 也是最优。秩函数 \\(r(A)=\\max\\{|I|:I\\subseteq A, I\\in\\mathcal I\\}\\) 满足次模性，是「贪心+凸」在这片土地上的对应物。",-1)),(r(),o(i,null,{default:t(()=>[l(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%7CO%7C%20%3E%20%7CG%EF%BD%9C%3F%22%5D%20--%3E%7C%22%E4%BA%A4%E6%8D%A2%E5%85%AC%E7%90%86%22%7C%20R%5B%22O%E2%88%96G%20%E5%8F%AF%E4%BE%9B%E7%BB%99%20G%20%E6%89%A9%E5%85%85%22%5D%0A%20%20R%20--%3E%20S%5B%22%E6%89%A9%E5%85%85%E5%85%83%E7%B4%A0%E6%9D%83%20%E2%89%A4%20%E8%B4%AA%E5%BF%83%E6%89%80%E5%BC%83%22%5D%0A%20%20S%20--%3E%20T%5B%22%E9%80%90%E6%AD%A5%E6%9B%BF%E6%8D%A2%20O%E2%86%92G%22%5D%0A%20%20T%20--%3E%20U%5B%22G%20%E4%BA%A6%E6%9C%80%E4%BC%98%3A%20%E8%B4%AA%E5%BF%83%E6%88%90%E7%AB%8B%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=E('<p><span class="marginnote">数字实例：三角形三条边 ab、ac、bc 构成图拟阵（独立 = 森林）。\\(A=\\{\\)ab\\(\\}\\)、\\(B=\\{\\)ac, bc\\(\\}\\) 都独立且 \\(|A|=1\\lt|B|=2\\)，交换公理保证 ac 或 bc 可补进 \\(A\\) 仍无环；反过来把 ab 补进 \\(B\\) 恰好围成三角形——交换是「大的喂小的」的单向选择权，Kruskal 删环重选正是在这条公理上滑动。</span></p><p><span class="marginnote">常见误区：把「贪心某次对了」当成「问题有拟阵结构」。经典反例：币值 1、3、4 的找零，贪心 4+3+3+1 用 4 枚，最优 4+4 用 2 枚——找零系统的独立集不满足交换公理，贪心无靠山。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>判断一个具体问题是否落在拟阵上，常用「它是不是某矩阵的线性无关列」（线性拟阵）或「某图的森林」（图拟阵）来认领。两个拟阵的<strong>交</strong>上的最大独立集问题，贪心失效，要用 Edmonds 的交算法（多项式但复杂度高）；三个及以上拟阵交已是 NP-hard。拟阵并、对偶拟阵是进阶工具，本课只立路标。</p><p><span class="marginnote">直觉类比：单个拟阵像一条「只进不退」的单行道，贪心直行即达；拟阵交像两条单行道交叉，直行会撞，需要信号灯（增广路算法）调度。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>拟阵 = 遗传 + 交换的独立系；交换公理是贪心定理的生死线。</li><li>Kruskal 是图拟阵上贪心定理的实例；秩函数次模。</li><li>双拟阵交多项式可解，三拟阵交 NP-hard——工具边界要认得。</li><li>出处：Whitney「On the Abstract Properties of Linear Dependence」1935；Edmonds「Matroids and the Greedy Algorithm」1971。</li></ul>',7))])}const f=A(p,[["render",m]]);export{_ as __pageData,f as default};
